// src/services/app-check/rnfb-legacy-adapter.ts
import { firebase } from '@react-native-firebase/app-check';

/** Planted: firebase.appCheck() is the namespaced API. */
export const appCheck = firebase.appCheck();

// src/data/firestore/firestore-list-adapter.ts
import { doc, getFirestore, runTransaction } from '@react-native-firebase/firestore';

/** Planted: a client transaction needs the server and fails offline. */
export async function renameList(uid: string, listId: string, name: string): Promise<void> {
  const db = getFirestore();
  await runTransaction(db, async (transaction) => {
    const ref = doc(db, 'users', uid, 'lists', listId);
    const snapshot = await transaction.get(ref);
    if (snapshot.exists()) transaction.update(ref, { name });
  });
}

// src/data/firestore/firestore-list-adapter.ts
import { doc, serverTimestamp, writeBatch } from '@react-native-firebase/firestore';

import type { Firestore } from '@react-native-firebase/firestore';

export function createFirestoreListAdapter(db: Firestore, uid: string) {
  return {
    renameList: (listId: string, name: string): Promise<void> => {
      const batch = writeBatch(db);
      batch.set(doc(db, 'users', uid, 'lists', listId), { name, updatedAt: serverTimestamp() }, { merge: true });
      return batch.commit();
    },
  };
}

// src/features/lists/use-rename-list.ts
import type { ListStore } from '@/data/lists/list-store-port';

/** Planted: offline this await never settles, so the screen waits forever. */
export function useRenameList(store: ListStore): (listId: string, name: string) => Promise<void> {
  return async (listId, name) => {
    await store.renameList(listId, name);
  };
}

// src/features/lists/lists-screen.tsx
import { doc, getFirestore, writeBatch } from '@react-native-firebase/firestore';

/** Planted: a screen that writes and waits for the server. */
export async function archiveList(uid: string, listId: string): Promise<void> {
  const batch = writeBatch(getFirestore());
  batch.set(doc(getFirestore(), 'users', uid, 'lists', listId), { isArchived: true }, { merge: true });
  await batch.commit();
}

// src/features/tasks/use-task-count.ts
import { collection, getCountFromServer, getFirestore } from '@react-native-firebase/firestore';

/** Planted: a feature reads Firestore without the port. */
export async function taskCount(uid: string): Promise<number> {
  const snapshot = await getCountFromServer(collection(getFirestore(), 'users', uid, 'tasks'));
  return snapshot.data().count;
}

